#: The experiment-config key the orchestrator resolves Q-15 from. A key NAME, not a
#: value: the value is the Student's TE 18.2 forbidden choice and is UNSET today.
Q15_CONFIG_KEY: str = "gim_interpolation_rule"


def interpolation_rule_from(experiment: Mapping[str, Any]) -> str | None:
    """Resolve the Q-15 interpolation rule from the governed experiment config.

    Returns None while the rule is UNSET -- absent, empty, or carrying the literal
    `TBD -- freeze gate` sentinel. No default is supplied here or anywhere: TE 18.2,
    quoted -- "No implementer or coding agent may fill such a value by convenience."
    """
    value = experiment.get(Q15_CONFIG_KEY)
    if value is None:
        return None
    text = str(value).strip()
    if not text or text == TBD_SENTINEL:
        return None
    return text


def _parse_utc(value: Any, *, resource: str, field: str) -> dt.datetime:
    text = str(value)
    if text.endswith("Z"):  # the `Z` suffix parses only from Python 3.11; 3.10 needs +00:00
        text = text[:-1] + "+00:00"
    try:
        parsed = dt.datetime.fromisoformat(text)
    except (TypeError, ValueError) as exc:
        raise ComparatorError(
            resource,
            f"{field} is not an ISO-8601 timestamp ({value!r}); an ordering check "
            f"over an unparseable timestamp proves nothing (R-60 obligation 2)",
        ) from exc
    if parsed.tzinfo is None:
        raise ComparatorError(
            resource,
            f"{field} carries no timezone ({value!r}); a naive timestamp cannot "
            f"evidence ordering across sessions",
        )
    return parsed


def evaluate_generation_gates(
    *,
    interpolation_rule: str | None,
    hand_check: Mapping[str, Any] | None,
    overlap_audit: Mapping[str, Any] | None,
    generation_attempt_utc: dt.datetime,
) -> None:
    """R-60's generation preconditions, in order; the first violated one raises.

    Order: obligation 1 (Q-15 set), then obligation 2 (hand-check exists, carries its
    worked arithmetic, and its timestamp PRECEDES this attempt), then the overlap
    audit's ordering (registered, and its recorded timestamp PRECEDES this attempt --
    a retrospective audit is not accepted, because obligation 1's refusal is a
    mitigation that expires the moment Q-15 is decided).

    Raises
    ------
    ComparatorError
        naming the violated gate.
    """
    if interpolation_rule is None:
        raise ComparatorError(
            "GIM comparator generation",
            "REFUSED: the interpolation rule (bilinear in space, linear in time, with "
            "a longitude-rotation correction) is a TE 18.2 Student-owned forbidden "
            "choice (Q-15) and it is UNSET; specifying the mechanism while leaving "
            "the value implicitly fillable is exactly what TE 18.2 prohibits, so "
            "generation refuses while it stands -- the zero-TBD preflight's shape "
            "(R-60 obligation 1). This refusal is the deliverable while Q-15 is open",
        )
    if hand_check is None:
        raise ComparatorError(
            "GIM comparator generation",
            "no interpolation hand-check record exists; EV-11 places the "
            "hand-calculation BEFORE comparator generation, and a comparator "
            "generated before the hand-check FAILS rather than being accepted "
            "retrospectively (R-60 obligation 2)",
        )
    if not str(hand_check.get("worked_arithmetic", "") or "").strip():
        raise ComparatorError(
            "GIM comparator generation",
            "the hand-check record carries no worked arithmetic; FR-P1-04-18's "
            "criterion names the hand-checked sample WITH its worked arithmetic",
        )
    checked_at = _parse_utc(
        hand_check.get("checked_at_utc"),
        resource="GIM comparator generation",
        field="hand_check.checked_at_utc",
    )
    if checked_at >= generation_attempt_utc:
        raise ComparatorError(
            "GIM comparator generation",
            f"the hand-check timestamp ({checked_at.isoformat()}) does not PRECEDE "
            f"this generation attempt ({generation_attempt_utc.isoformat()}); a "
            f"comparator generated before the hand-check fails rather than being "
            f"accepted retrospectively (EV-11; R-60 obligation 2)",
        )
    if overlap_audit is None:
        raise ComparatorError(
            "GIM comparator generation",
            "no registered gim_network_overlap_flag audit exists; the audit's "
            "recorded timestamp must PRECEDE comparator generation (R-60's "
            "Constraint, Recommendation 41) -- obligation 1's Q-15 refusal is a "
            "mitigation that EXPIRES, so the ordering is enforced here rather than "
            "assumed. No independence claim may be made before that audit "
            "(Vision 6.10)",
        )
    audited_at = _parse_utc(
        overlap_audit.get("recorded_at_utc"),
        resource="GIM comparator generation",
        field="overlap_audit.recorded_at_utc",
    )
    if audited_at >= generation_attempt_utc:
        raise ComparatorError(
            "GIM comparator generation",
            f"the overlap audit's recorded timestamp ({audited_at.isoformat()}) does "
            f"not PRECEDE this generation attempt "
            f"({generation_attempt_utc.isoformat()}); a retrospective audit is NOT "
            f"accepted (R-60's Constraint, the same enforceable shape as the "
            f"hand-check ordering)",
        )


def generate_comparator(
    *,
    interpolation_rule: str | None,
    hand_check: Mapping[str, Any] | None,
    overlap_audit: Mapping[str, Any] | None,
    injection_mode: bool = False,
    now: dt.datetime | None = None,
    comparator_inputs: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Attempt GIM comparator generation.

    Before D-70 (2026-09-26), every real invocation refused at obligation 1:
    Q-15 was unset and no default was ever supplied. Q-15 is now frozen
    (`configs/experiment.yaml: gim_interpolation_rule = "C"`), so a real
    invocation now proceeds past obligation 1 -- and past obligations 2-3 only
    when REAL (non-injected) `hand_check` and `overlap_audit` records exist
    with timestamps preceding this attempt. `injection_mode=True` still marks
    a negative-control attempt driven by injected state: the gates are
    evaluated exactly as for a real attempt, and if the injected state
    satisfies them the attempt STILL refuses -- injected state is never
    governed evidence, and proving the gates reject violations must never
    itself generate a comparator. This is unchanged by D-70.

    When every gate passes on REAL evidence (`injection_mode=False`) and
    `comparator_inputs` supplies `{ionex_path, station_lat, station_lon,
    target_epoch_utc}`, the interpolation workload actually runs
    (`compute_comparison`, rule "C" only -- D-70 never authorized generating
    the real comparator under rule "B", which stays sensitivity-only) and its
    result is returned. Without `comparator_inputs`, a fully-passing real
    attempt still refuses, naming that no comparator inputs were supplied --
    gates passing is necessary, not sufficient, to produce a value.

    Returns
    -------
    dict | None
        The `compute_comparison` result when generation succeeds; otherwise
        this function always raises (it never returns None on a refusal path
        -- every refusal is a raised `ComparatorError`).

    Raises
    ------
    ComparatorError
        from the violated gate; from the injection-mode terminal refusal;
        from an unset rule other than "C" when comparator_inputs is supplied
        (rule "B" is never used to generate the real comparator); or from a
        real, fully-passing attempt with no comparator_inputs supplied.
    """
    attempt_utc = now if now is not None else dt.datetime.now(dt.timezone.utc)
    evaluate_generation_gates(
        interpolation_rule=interpolation_rule,
        hand_check=hand_check,
        overlap_audit=overlap_audit,
        generation_attempt_utc=attempt_utc,
    )
    if injection_mode:
        raise ComparatorError(
            "GIM comparator generation",
            "injection-mode gate evaluation complete: every gate passed on the "
            "INJECTED state, and generation is refused anyway -- injected state is "
            "not governed evidence, and no comparator is generated by this unit "
            "(the refusals are the deliverable)",
        )
    if comparator_inputs is None:
        raise ComparatorError(
            "GIM comparator generation",
            "every gate passed on real evidence, but no comparator_inputs "
            "(ionex_path, station_lat, station_lon, target_epoch_utc) were "
            "supplied; gates passing is necessary, not sufficient, to "
            "produce a value -- the caller must name what to compute",
        )
    if interpolation_rule != "C":
        raise ComparatorError(
            "GIM comparator generation",
            f"the frozen Q-15 rule is 'C' (D-70); the real comparator is "
            f"never generated under rule {interpolation_rule!r} -- rule 'B' "
            f"is a sensitivity analysis only, reachable through "
            f"compute_comparison directly, never through this gated path",
        )
    result = compute_comparison(
        ionex_path=Path(comparator_inputs["ionex_path"]),
        station_lat=float(comparator_inputs["station_lat"]),
        station_lon=float(comparator_inputs["station_lon"]),
        target_epoch_utc=_parse_utc(
            comparator_inputs["target_epoch_utc"],
            resource="GIM comparator generation",
            field="comparator_inputs.target_epoch_utc",
        ),
        rule=interpolation_rule,
    )
    result["map_to_map_statement"] = MAP_TO_MAP_STATEMENT
    result["spatial_representativeness_statement"] = SPATIAL_REPRESENTATIVENESS_STATEMENT
    return result


#: Grid parameters this codebase's acquired CODE final GIM files carry (Q15 decision
#: document context, verified 2026-09-26 against `codg1000.22i.Z`'s own header): 2.5 deg
#: latitude by 5 deg longitude, hourly maps, values stored in 0.1 TECU (exponent -1).
#: This is a VALIDATION reference for provenance/day checking, never an interpolation
#: parameter -- Q-15's rule remains unset regardless of these matching.
IONEX_EXPECTED_GRID: dict[str, float] = {
    "lat1": 87.5,
    "lat2": -87.5,
    "dlat": -2.5,
    "lon1": -180.0,
    "lon2": 180.0,
    "dlon": 5.0,
    "exponent": -1,
}

_IONEX_LABEL_COL = 60
_IONEX_DAY_RE = re.compile(r"GLOBAL IONOSPHERE MAPS FOR DAY\s+(\d+),\s+(\d+)")


def _ionex_label(line: str) -> str:
    return line[_IONEX_LABEL_COL:].strip() if len(line) > _IONEX_LABEL_COL else line.strip()


def _decompress_ionex_bytes(path: Path) -> bytes:
    """Decompress a CODE final GIM file: `.gz` via stdlib `gzip`, legacy Unix
    `.Z` (compress format, magic 0x1F 0x9D) by shelling out to a `gzip`
    executable on PATH -- Python's stdlib `gzip` module decodes only the DEFLATE
    format and cannot read `.Z`. Fails closed, naming the file, if neither the
    format nor a working decompressor is available (team.md's integrity-failure
    convention: never continue silently past a failed read)."""
    suffix = path.suffix.lower()
    if suffix == ".gz":
        import gzip

        try:
            with gzip.open(path, "rb") as handle:
                return handle.read()
        except OSError as exc:
            raise ComparatorError(
                str(path), f"cannot decompress .gz IONEX file: {exc}"
            ) from exc
    try:
        result = subprocess.run(
            ["gzip", "-d", "-c", str(path)],
            capture_output=True,
            check=True,
        )
    except (OSError, subprocess.CalledProcessError) as exc:
        raise ComparatorError(
            str(path),
            f"cannot decompress legacy .Z (Unix-compress) IONEX file: {exc}; a "
            f"'gzip' executable capable of decoding Unix-compress .Z is required "
            f"on PATH (Python's stdlib gzip module cannot read this format)",
        ) from exc
    return result.stdout


def parse_ionex_header(text: str) -> dict[str, Any]:
    """Parse ONLY the structural header fields of an IONEX file -- grid geometry,
    epochs, station count/list, and the CODE day/year comment. Never reads any
    TEC map value; this function stops at `END OF HEADER` and looks no further.

    Returns a dict with keys: `day_of_year`, `year` (from the CODE day comment,
    or None if absent -- some non-CODE IONEX products carry no such comment),
    `epoch_first_map_utc`, `epoch_last_map_utc`, `interval_s`, `num_maps`,
    `num_stations`, `stations` (sorted list of lowercase 4-char codes),
    `grid` (lat1/lat2/dlat/lon1/lon2/dlon), `exponent`.

    Raises
    ------
    ComparatorError
        if `END OF HEADER` is never reached, or a required field is missing --
        an incomplete header cannot be validated and is not silently accepted.
    """
    lines = text.splitlines()
    fields: dict[str, Any] = {
        "day_of_year": None,
        "year": None,
        "stations": [],
    }
    collecting_stations = False
    saw_end_of_header = False
    for line in lines:
        label = _ionex_label(line)
        if label == "END OF HEADER":
            saw_end_of_header = True
            break
        if label == "COMMENT":
            text_part = line[:_IONEX_LABEL_COL] if len(line) > _IONEX_LABEL_COL else line
            match = _IONEX_DAY_RE.search(text_part)
            if match:
                fields["day_of_year"] = int(match.group(1))
                fields["year"] = int(match.group(2))
            stripped = text_part.strip()
            if stripped == "List of stations:":
                collecting_stations = True
                continue
            if collecting_stations:
                tokens = stripped.split()
                if tokens and all(len(tok) == 4 and tok.isalnum() for tok in tokens):
                    fields["stations"].extend(tok.lower() for tok in tokens)
                else:
                    collecting_stations = False
            continue
        collecting_stations = False
        if label == "EPOCH OF FIRST MAP":
            y, mo, d, h, mi, s = line.split()[:6]
            fields["epoch_first_map_utc"] = dt.datetime(
                int(y), int(mo), int(d), int(h), int(mi), int(s), tzinfo=dt.timezone.utc
            ).isoformat()
        elif label == "EPOCH OF LAST MAP":
            y, mo, d, h, mi, s = line.split()[:6]
            fields["epoch_last_map_utc"] = dt.datetime(
                int(y), int(mo), int(d), int(h), int(mi), int(s), tzinfo=dt.timezone.utc
            ).isoformat()
        elif label == "INTERVAL":
            fields["interval_s"] = int(line.split()[0])
        elif label == "# OF MAPS IN FILE":
            fields["num_maps"] = int(line.split()[0])
        elif label == "# OF STATIONS":
            fields["num_stations"] = int(line.split()[0])
        elif label == "EXPONENT":
            fields["exponent"] = int(line.split()[0])
        elif label == "LAT1 / LAT2 / DLAT":
            lat1, lat2, dlat = (float(v) for v in line.split()[:3])
            fields["grid"] = fields.get("grid", {})
            fields["grid"].update({"lat1": lat1, "lat2": lat2, "dlat": dlat})
        elif label == "LON1 / LON2 / DLON":
            lon1, lon2, dlon = (float(v) for v in line.split()[:3])
            fields["grid"] = fields.get("grid", {})
            fields["grid"].update({"lon1": lon1, "lon2": lon2, "dlon": dlon})

    if not saw_end_of_header:
        raise ComparatorError(
            "IONEX header parse",
            "no 'END OF HEADER' label found; an incomplete or truncated header "
            "cannot be validated and is not accepted",
        )
    fields["stations"] = sorted(set(fields["stations"]))
    missing = [
        key
        for key in (
            "epoch_first_map_utc",
            "interval_s",
            "num_maps",
            "num_stations",
            "grid",
            "exponent",
        )
        if key not in fields
    ]
    if missing:
        raise ComparatorError(
            "IONEX header parse",
            f"header is missing required field(s) {missing}; an incomplete header "
            f"is refused rather than partially trusted",
        )
    return fields


def validate_ionex_file(
    path: Path,
    *,
    expected_year: int,
    expected_doy: int,
    expected_grid: Mapping[str, float] = IONEX_EXPECTED_GRID,
    grid_tolerance: float = 1e-6,
) -> dict[str, Any]:
    """Decompress and structurally validate one CODE final GIM file: day/year
    matches the acquisition's own filename-derived identity, and the grid
    geometry matches this project's expected CODE product shape. Reads no TEC
    map value -- structural/provenance validation only.

    Raises
    ------
    ComparatorError
        naming the file and the specific mismatch, on any of: day/year mismatch
        against the file's own CODE comment, grid geometry mismatch, or
        exponent mismatch. Fails closed -- an ambiguous or absent day/year
        comment (a non-CODE product served instead of the expected one) is a
        mismatch, not silently accepted.
    """
    raw = _decompress_ionex_bytes(path)
    text = raw.decode("ascii", errors="replace")
    header = parse_ionex_header(text)

    if header["day_of_year"] is None or header["year"] is None:
        raise ComparatorError(
            str(path),
            "no 'CODE'S GLOBAL IONOSPHERE MAPS FOR DAY nnn, YYYY' comment found; "
            "cannot confirm this file is the expected CODE final product for "
            "the expected day, so it is refused rather than assumed correct",
        )
    if (header["day_of_year"], header["year"]) != (expected_doy, expected_year):
        raise ComparatorError(
            str(path),
            f"day/year mismatch: file's own header states day {header['day_of_year']}, "
            f"{header['year']}; expected day {expected_doy}, {expected_year} from "
            f"the acquisition's filename-derived identity",
        )
    grid = header["grid"]
    for key, expected_value in expected_grid.items():
        if key == "exponent":
            actual = header["exponent"]
        else:
            actual = grid.get(key)
        if actual is None or abs(actual - expected_value) > grid_tolerance:
            raise ComparatorError(
                str(path),
                f"grid parameter '{key}' mismatch: file has {actual}, expected "
                f"{expected_value} (+/- {grid_tolerance}) -- a differently-gridded "
                f"product must not be silently accepted as the expected CODE final "
                f"2.5x5 degree hourly product",
            )
    return header


def verify_ionex_bundle(
    directory: Path,
    *,
    manifest_name: str = "sha256_manifest.json",
    validate_day_year: bool = True,
) -> dict[str, Any]:
    """Re-hash every manifested file in `directory` against
    `sha256_manifest.json` and, when `validate_day_year` is True, structurally
    validate each file's day/year and grid geometry (`validate_ionex_file`).

    Derives each file's expected (year, day-of-year) from its own VERBATIM
    filename -- the short form `codgDDD0.YYi.Z` and the long form
    `*_YYYYDDD0000_*` -- never from a separately-declared list, so this check
    cannot be satisfied by a manifest that merely agrees with itself.

    Raises
    ------
    ComparatorError
        naming the file, on: a manifested file missing from disk, a hash
        mismatch, a filename that fits neither known day-encoding pattern, or
        (when `validate_day_year`) any `validate_ionex_file` failure. Never
        continues past the first failure -- fail-closed, per this project's
        integrity-check convention.
    """
    import json

    manifest_path = directory / manifest_name
    if not manifest_path.is_file():
        raise ComparatorError(str(manifest_path), "manifest file does not exist")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8-sig"))

    short_re = re.compile(r"^codg(\d{3})0\.(\d{2})i\.[Zz]$")
    long_re = re.compile(r"_(\d{4})(\d{3})0000_")

    checked = 0
    for filename, expected_hash in manifest.items():
        file_path = directory / filename
        if not file_path.is_file():
            raise ComparatorError(
                str(file_path),
                f"listed in {manifest_name} with hash {expected_hash} but missing "
                f"on disk",
            )
        actual_hash = sha256_of_file(file_path)
        if actual_hash != expected_hash:
            raise ComparatorError(
                str(file_path),
                f"hash mismatch: manifest records {expected_hash}, actual is "
                f"{actual_hash}",
            )
        if validate_day_year:
            short_match = short_re.match(filename)
            long_match = long_re.search(filename)
            if short_match:
                doy, yy = int(short_match.group(1)), int(short_match.group(2))
                year = 2000 + yy
            elif long_match:
                year, doy = int(long_match.group(1)), int(long_match.group(2))
            else:
                raise ComparatorError(
                    str(file_path),
                    f"filename '{filename}' matches neither the short "
                    f"(codgDDD0.YYi.Z) nor long (*_YYYYDDD0000_*) CODE final GIM "
                    f"naming pattern; its expected day/year cannot be derived, so "
                    f"it is refused rather than skipped",
                )
            validate_ionex_file(file_path, expected_year=year, expected_doy=doy)
        checked += 1
    return {"files_checked": checked, "manifest_path": str(manifest_path)}


#: The Q-15 rules this module can actually compute a value for. "C" is the frozen rule
#: (D-70, evidence/DECISIONS.md); "B" is implemented ONLY as the labeled Jan-Nov
#: sensitivity analysis D-70 retains -- never usable to generate the real comparator.
#: "A" (nearest) has no computation here: the decision document's own recommendation
#: is that a crude bound is never the frozen confirmatory rule (D-70).
IMPLEMENTED_RULES: tuple[str, ...] = ("B", "C")

_MAP_START = "START OF TEC MAP"
_MAP_END = "END OF TEC MAP"
_MAP_EPOCH = "EPOCH OF CURRENT MAP"
_MAP_LATROW = "LAT/LON1/LON2/DLON/H"
_MISSING_SENTINEL = 9999


def _parse_latrow_header(line: str) -> dict[str, float]:
    """Fixed-width IONEX lat-row header: lat(8) lon1(6) lon2(6) dlon(6) h(6)."""
    return {
        "lat": float(line[0:8]),
        "lon1": float(line[8:14]),
        "lon2": float(line[14:20]),
        "dlon": float(line[20:26]),
    }


def parse_ionex_maps(
    text: str,
) -> list[tuple[dt.datetime, dict[tuple[float, float], int]]]:
    """Parse every TEC map's raw grid values (fixed-width I5 fields, 16 per line)
    after `END OF HEADER`. Values are RAW (unscaled by exponent) -- scaling and
    the `9999` missing-data sentinel are the caller's business
    (`compute_comparison`), so this function is a faithful, lossless transcription
    of the file's own numbers.

    Returns a list of (epoch_utc, grid) pairs, `grid` keyed by
    `(lat, lon)` -> raw int value, one entry per map, in file order.

    Raises
    ------
    ComparatorError
        if a `START OF TEC MAP` block has no matching `END OF TEC MAP`, or an
        `EPOCH OF CURRENT MAP` line is malformed -- an unparseable map is
        refused, never silently skipped.
    """
    lines = text.splitlines()
    i = 0
    n = len(lines)
    while i < n and _ionex_label(lines[i]) != "END OF HEADER":
        i += 1
    i += 1  # past END OF HEADER

    maps: list[tuple[dt.datetime, dict[tuple[float, float], int]]] = []
    while i < n:
        label = _ionex_label(lines[i])
        if label != _MAP_START:
            i += 1
            continue
        i += 1
        if i >= n or _ionex_label(lines[i]) != _MAP_EPOCH:
            raise ComparatorError(
                "IONEX map parse",
                f"START OF TEC MAP at line {i} has no EPOCH OF CURRENT MAP "
                f"line following it",
            )
        parts = lines[i].split()[:6]
        if len(parts) != 6:
            raise ComparatorError(
                "IONEX map parse", f"malformed EPOCH OF CURRENT MAP line: {lines[i]!r}"
            )
        y, mo, d, h, mi, s = (int(p) for p in parts)
        epoch = dt.datetime(y, mo, d, h, mi, s, tzinfo=dt.timezone.utc)
        i += 1
        grid: dict[tuple[float, float], int] = {}
        found_end = False
        while i < n:
            row_label = _ionex_label(lines[i])
            if row_label == _MAP_END:
                found_end = True
                i += 1
                break
            if row_label == _MAP_LATROW:
                header = _parse_latrow_header(lines[i])
                lat = header["lat"]
                lon1, lon2, dlon = header["lon1"], header["lon2"], header["dlon"]
                ncols = round((lon2 - lon1) / dlon) + 1
                i += 1
                values: list[int] = []
                while len(values) < ncols and i < n:
                    # Data lines carry no trailing label -- unlike header lines,
                    # a full 16-value data line is 80 chars wide (16 x 5), WIDER
                    # than the header label column (60), so it must NOT be
                    # truncated there (that discarded the last 4 values on
                    # every full line -- found by this exact hand-check
                    # reproduction test failing).
                    content = lines[i]
                    for k in range(0, len(content), 5):
                        if len(values) >= ncols:
                            break
                        chunk = content[k : k + 5]
                        if chunk.strip():
                            values.append(int(chunk))
                    i += 1
                for col, value in enumerate(values):
                    lon = round(lon1 + col * dlon, 4)
                    grid[(round(lat, 4), lon)] = value
                continue
            i += 1
        if not found_end:
            raise ComparatorError(
                "IONEX map parse",
                f"map at epoch {epoch.isoformat()} has no END OF TEC MAP line",
            )
        maps.append((epoch, grid))
    return maps


def _normalize_lon(lon: float, lon1: float) -> float:
    """Wrap `lon` into `[lon1, lon1 + 360)` -- the grid's own longitude range."""
    return ((lon - lon1) % 360.0) + lon1


def _bilinear_at(
    grid: Mapping[tuple[float, float], int],
    *,
    grid_meta: Mapping[str, float],
    lat: float,
    lon: float,
    resource: str,
) -> float:
    """Four-corner bilinear lookup in RAW grid units (unscaled). Fails closed on
    an out-of-bounds coordinate, a missing grid cell, or a `9999` sentinel corner
    -- an interpolation through a data gap is refused, never silently produced."""
    lat1, dlat = grid_meta["lat1"], grid_meta["dlat"]
    lat2 = grid_meta["lat2"]
    lon1, dlon = grid_meta["lon1"], grid_meta["dlon"]
    nlat = round((lat2 - lat1) / dlat) + 1
    nlon = round((grid_meta["lon2"] - lon1) / dlon) + 1

    lon_n = _normalize_lon(lon, lon1)
    lat_idx_f = (lat - lat1) / dlat
    lon_idx_f = (lon_n - lon1) / dlon
    lat0 = math.floor(lat_idx_f)
    lon0 = math.floor(lon_idx_f)
    lat_frac = lat_idx_f - lat0
    lon_frac = lon_idx_f - lon0
    lat1i, lon1i = lat0 + 1, lon0 + 1

    if not (0 <= lat0 <= nlat - 2):
        raise ComparatorError(
            resource,
            f"latitude {lat} is outside the grid's interpolable range "
            f"[{lat2}, {lat1}]",
        )
    if not (0 <= lon0 <= nlon - 2):
        raise ComparatorError(
            resource,
            f"normalized longitude {lon_n} (from {lon}) is outside the grid's "
            f"interpolable range after wrap",
        )

    def corner(li: int, lj: int) -> float:
        lat_val = round(lat1 + li * dlat, 4)
        lon_val = round(lon1 + lj * dlon, 4)
        raw = grid.get((lat_val, lon_val))
        if raw is None:
            raise ComparatorError(
                resource, f"grid cell (lat={lat_val}, lon={lon_val}) not found in map"
            )
        if abs(raw) >= _MISSING_SENTINEL:
            raise ComparatorError(
                resource,
                f"grid cell (lat={lat_val}, lon={lon_val}) is the IONEX "
                f"missing-data sentinel ({raw}); cannot interpolate through a gap",
            )
        return float(raw)

    v00 = corner(lat0, lon0)
    v01 = corner(lat0, lon1i)
    v10 = corner(lat1i, lon0)
    v11 = corner(lat1i, lon1i)
    return (
        (1 - lat_frac) * (1 - lon_frac) * v00
        + (1 - lat_frac) * lon_frac * v01
        + lat_frac * (1 - lon_frac) * v10
        + lat_frac * lon_frac * v11
    )


def compute_comparison(
    *,
    ionex_path: Path,
    station_lat: float,
    station_lon: float,
    target_epoch_utc: dt.datetime,
    rule: str,
) -> dict[str, Any]:
    """Compute one CODE final GIM VTEC comparator value at a station coordinate
    and epoch, under `rule` ("B" or "C" -- `IMPLEMENTED_RULES`). This is the
    interpolation workload `generate_comparator`'s docstring named as downstream
    work; it is invoked from `generate_comparator` only after
    `evaluate_generation_gates` has passed on REAL (non-injected) evidence, and
    only for rule "C" (the frozen Q-15 choice, D-70) -- rule "B" remains a
    sensitivity-analysis-only computation, callable here directly but never
    reached through the gated `generate_comparator` path.

    Epoch bracketing: if `target_epoch_utc` exactly equals a map epoch, only
    that map is consulted (no temporal blend, `f_t = 0.0`) -- an exact-boundary
    target is not an error and does not divide by zero. If it falls strictly
    between two maps, standard linear blending applies. A target outside the
    file's map range refuses by name.

    Raises
    ------
    ComparatorError
        naming the file and reason, on: an unimplemented rule, a target epoch
        outside the file's range, an out-of-grid coordinate, a missing grid
        cell, or a `9999` sentinel corner (never silently masked or defaulted).
    """
    if rule not in IMPLEMENTED_RULES:
        raise ComparatorError(
            str(ionex_path),
            f"rule '{rule}' has no interpolation implemented here; only "
            f"{IMPLEMENTED_RULES} are (D-70's frozen 'C', and 'B' as the "
            f"labeled sensitivity analysis only)",
        )
    raw_bytes = _decompress_ionex_bytes(ionex_path)
    text = raw_bytes.decode("ascii", errors="replace")
    header = parse_ionex_header(text)
    maps = sorted(parse_ionex_maps(text), key=lambda m: m[0])
    if not maps:
        raise ComparatorError(str(ionex_path), "no TEC maps parsed from this file")

    lower: tuple[dt.datetime, dict[tuple[float, float], int]] | None = None
    upper: tuple[dt.datetime, dict[tuple[float, float], int]] | None = None
    for epoch, grid in maps:
        if epoch <= target_epoch_utc:
            lower = (epoch, grid)
        if epoch >= target_epoch_utc and upper is None:
            upper = (epoch, grid)
    if lower is None or upper is None:
        raise ComparatorError(
            str(ionex_path),
            f"target epoch {target_epoch_utc.isoformat()} is outside this "
            f"file's map range [{maps[0][0].isoformat()}, {maps[-1][0].isoformat()}]",
        )

    grid_meta = header["grid"]
    exponent = header["exponent"]
    resource = f"{ionex_path}:{station_lat},{station_lon}@{target_epoch_utc.isoformat()}"

    if lower[0] == upper[0]:
        # Exact epoch match: only one map is consulted, no temporal blend.
        shift = 0.0
        raw_value = _bilinear_at(
            lower[1],
            grid_meta=grid_meta,
            lat=station_lat,
            lon=_normalize_lon(station_lon + shift, grid_meta["lon1"]),
            resource=resource,
        )
        value_tecu = raw_value * (10.0**exponent)
        return {
            "value_tecu": value_tecu,
            "rule": rule,
            "station_lat": station_lat,
            "station_lon": station_lon,
            "target_epoch_utc": target_epoch_utc.isoformat(),
            "ionex_file": ionex_path.name,
            "map_epochs_used": [lower[0].isoformat()],
            "f_t": 0.0,
            "exact_epoch_match": True,
            "rotation_shift_deg": {"lower": 0.0, "upper": 0.0},
        }

    total_s = (upper[0] - lower[0]).total_seconds()
    dt_lower_s = (target_epoch_utc - lower[0]).total_seconds()
    dt_upper_s = (upper[0] - target_epoch_utc).total_seconds()
    f_t = dt_lower_s / total_s

    if rule == "C":
        rotate_lower = 15.0 * (dt_lower_s / 3600.0)
        rotate_upper = -15.0 * (dt_upper_s / 3600.0)
    else:  # rule == "B": no rotation correction (the sensitivity analysis)
        rotate_lower = 0.0
        rotate_upper = 0.0

    raw_lower = _bilinear_at(
        lower[1],
        grid_meta=grid_meta,
        lat=station_lat,
        lon=_normalize_lon(station_lon + rotate_lower, grid_meta["lon1"]),
        resource=resource,
    )
    raw_upper = _bilinear_at(
        upper[1],
        grid_meta=grid_meta,
        lat=station_lat,
        lon=_normalize_lon(station_lon + rotate_upper, grid_meta["lon1"]),
        resource=resource,
    )
    value_tecu = (raw_lower * (1 - f_t) + raw_upper * f_t) * (10.0**exponent)
    return {
        "value_tecu": value_tecu,
        "rule": rule,
        "station_lat": station_lat,
        "station_lon": station_lon,
        "target_epoch_utc": target_epoch_utc.isoformat(),
        "ionex_file": ionex_path.name,
        "map_epochs_used": [lower[0].isoformat(), upper[0].isoformat()],
        "f_t": f_t,
        "exact_epoch_match": False,
        "rotation_shift_deg": {"lower": rotate_lower, "upper": rotate_upper},
    }


def compute_overlap_audit(
    *,
    network_station_codes: Iterable[str],
    target_stations: Mapping[str, str],
    source_description: str,
    recorded_at_utc: dt.datetime | None = None,
) -> dict[str, Any]:
    """Compute a `gim_network_overlap_flag` audit result under the D-71
    definition (evidence/DECISIONS.md, confirmed by owner instruction
    2026-09-26).

    RULE IMPLEMENTED (D-71-confirmed): overlap is a PRESENCE test --
    `gim_network_overlap_flag` is True iff ANY target station's own
    4-character IGS code appears among the CODE contributing stations in
    `network_station_codes`. This is the most direct reading of "network
    overlap" available from IONEX header metadata (which station's own
    receiver fed the comparator's underlying solution). D-71 states
    explicitly what this flag is NOT: it is not a weighting,
    influence-magnitude, or upstream-tie audit (a station whose code differs
    from a target but which still influences the regional solution through a
    nearby tied receiver is not detected by this rule -- an uncovered
    residual, named in D-71, not papered over), and a `False` result is not
    an independence claim (CODE's GIM is a global spherical-harmonic fit, not
    a per-cell average). December's status is NOT determined by this
    function on a January-November input and must never be extrapolated
    (D-71).

    Returns a dict shaped exactly as `evaluate_generation_gates` and
    `render_comparison_report` require: `gim_network_overlap_flag`,
    `recorded_at_utc` (ISO-8601, UTC). Additional keys (`rule`,
    `source_description`, `per_station`) carry the audit's own evidence and
    are additive -- present for review, never required by the gate.
    """
    codes = {c.strip().lower() for c in network_station_codes}
    per_station: dict[str, Any] = {}
    any_overlap = False
    for name, code in target_stations.items():
        present = code.strip().lower() in codes
        per_station[name] = {"code": code.strip().lower(), "present_in_network": present}
        any_overlap = any_overlap or present
    recorded = recorded_at_utc or dt.datetime.now(dt.timezone.utc)
    return {
        "gim_network_overlap_flag": any_overlap,
        "recorded_at_utc": recorded.isoformat(),
        "rule": (
            "presence (D-71, owner-confirmed 2026-09-26): True iff any target "
            "station's own 4-char IGS code appears in the audited CODE "
            "contributing-station network -- NOT an independence claim; does "
            "not detect overlap via a nearby tied receiver whose code differs "
            "from the target station's own code (named residual, D-71)"
        ),
        "source_description": source_description,
        "per_station": per_station,
    }


def render_comparison_report(
    *,
    comparison: Mapping[str, Any],
    overlap_audit: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """The reporting path for ANY GIM comparison -- and the disclosure chokepoint.

    Obligation 3 is enforced here BY CONSTRUCTION: the map-product-to-map-product
    limitation and the spatial-representativeness mismatch are emitted by this
    function, not left to a writer. The overlap-flag disclosure is keyed to THE
    COMPARISON'S EXISTENCE (this function being called with one), not to the audit
    having run: a comparison with no registered audit result FAILS, whatever the
    result would have been. The no-tuning statement cites the audit (obligation 4's
    partial control); the outside-tuning residual is named in the module docstring and
    is NOT discharged by this function.

    Raises
    ------
    ComparatorError
        when no registered overlap-audit result with its flag value exists -- the
        mandatory disclosure cannot be attached, so the comparison is not rendered.
    """
    if overlap_audit is None or "gim_network_overlap_flag" not in overlap_audit:
        raise ComparatorError(
            "GIM comparison report",
            "a GIM comparison exists but no registered overlap-audit result with its "
            "gim_network_overlap_flag value is available; emitting, serializing or "
            "reporting ANY GIM comparison with no registered overlap-audit result "
            "FAILS -- the trigger is the comparison's existence, and disclosure is "
            "mandatory whatever the result (Vision 6.10; FR-P1-04-9; R-60's "
            "Constraint). No independence claim precedes the audit",
        )
    return {
        "comparison": dict(comparison),
        "map_to_map_statement": MAP_TO_MAP_STATEMENT,
        "spatial_representativeness_statement": SPATIAL_REPRESENTATIVENESS_STATEMENT,
        "gim_network_overlap_flag": overlap_audit["gim_network_overlap_flag"],
        "overlap_audit_recorded_at_utc": str(overlap_audit.get("recorded_at_utc", "")),
        "no_tuning_statement": (
            "No fitting, tuning, optimisation or parameter search was performed on "
            "the GIM comparator (C-01 is generated, not trained); the independence "
            "claim, if any, cites the gim_network_overlap_flag audit recorded above "
            "and is never made before it (R-60 obligation 4 -- partial control; "
            "tuning performed outside gim.py and pasted in as a constant is reached "
            "by no check and remains a reporting-discipline obligation)"
        ),
    }
